import{_ as l,l as i,o as e,c as s,v as t,p as c,x as o,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"CLOCK 置换","description":"","frontmatter":{"title":"CLOCK 置换","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-replace.md","filePath":"cs/clock-replace.md","lastUpdated":1789023840000}'),h={name:"cs/clock-replace.md"};function C(E,a,_,m,A,u){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="clock-置换" tabindex="-1">CLOCK 置换 <a class="header-anchor" href="#clock-置换" aria-label="Permalink to &quot;CLOCK 置换&quot;">​</a></h1><div class="epigraph"><p>用页表上的访问位和一只转圈的指针逼近 LRU：看见「用过」就给第二次机会，否则淘汰。</p><footer>—— 据 Corbato 的 CLOCK；Silberschatz 对第二次机会与 NRU 的整理</footer></div><p><a href="/cs/page-replace">上一课</a>已经给出 FIFO、最优、LRU 与 Belady 异常，并点到时钟是廉价近似。硬件很少为每页提供精确时间戳。<a href="/cs/tlb-translate">TLB</a> 与页表项上通常只有访问位、脏位。缺口是把这两位收成<strong>可实现的时钟</strong>：第二次机会、NRU、以及指针转圈时与 <a href="/cs/tlb-shootdown">shootdown</a> 的关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LRU 要在每次访存更新「最旧」。把时间戳写进 DRAM 页表会毁性能。缺口不是再证明最优离线，而是：访问位置位由 MMU 做；置换代码周期性清位。时钟指针扫帧：访问位为 1 则清零并跳过（第二次机会）；为 0 则选中。脏页可再给一次机会（NRU 的四个类：未用干净最好牺牲，用过且脏最不该走）。</p><p>本课不把 Linux 的 active/inactive 双 LRU 链表画成唯一实现。</p><p><span class="marginnote">第二次机会是 FIFO 队列上检查访问位：到了队头若被用过，清位并放到队尾。CLOCK 用环形数组模拟同一逻辑，指针代替搬队列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护物理帧的环形扫描。缺页且无空闲：从指针处找访问位为 0 的帧；扫描时清 1。选中后若脏则写回，清 PTE，对本 CPU 冲 TLB，他核走已有 shootdown，再把帧交给缺页者。全局时钟扫全机；局部时钟只扫该进程配额——配额从哪来，下一课工作集。</p>',9)),(e(),c(d,null,{default:o(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HAND%5B%22%E6%97%B6%E9%92%9F%E6%8C%87%E9%92%88%22%5D%20--%3E%20A%7B%22%E8%AE%BF%E9%97%AE%E4%BD%8D%22%7D%0A%20%20A%20--%3E%7C1%7C%20CLR%5B%22%E6%B8%85%E4%BD%8D%2C%20%E6%8C%87%E9%92%88%E5%89%8D%E8%BF%9B%22%5D%0A%20%20A%20--%3E%7C0%7C%20VIC%5B%22%E7%89%BA%E7%89%B2%3A%20%E8%84%8F%E5%88%99%E5%86%99%E5%9B%9E%22%5D%0A%20%20VIC%20--%3E%20UNMAP%5B%22%E8%A7%A3%E6%98%A0%E5%B0%84%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CLOCK 把<a href="/cs/locality-principle">局部性</a>变成一位滞后：最近用过的页不会在这一圈被扔掉。它不是真 LRU，于是存在扫描风暴：所有页访问位都是 1 时，退化为 FIFO。实现上会隔一段时间批量清位，或与后课工作集窗口一起限扫描长度。</p><p>不要在这里重导页表：访问位是分页课已有的属性，本课只读它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ARC、CAR 等专利算法当主干。不把 NUMA 远程帧的扫描优先级写完。CLOCK 不解决「工作集大于内存」——再精致的近似 LRU 也会抖，那是后两课。脏文件页可以丢（还能从文件再读），匿名脏页必须有交换槽，来源课再分。</p><p>后课默认：在线算法用访问位逼近 LRU。何谓「近期真正需要的页集合」，下一课工作集。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时钟与第二次机会用访问位近似 LRU，避免时间戳。</li><li>NRU 用访问/脏两位分优先级。</li><li>工作集模型解释该驻留哪些页，是下一课。</li><li>出处：Corbato CLOCK；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const L=l(h,[["render",C]]);export{B as __pageData,L as default};
